		//    mc.buttonMode = true;
		//    
		//    // Thêm sự kiện click
		//    mc.addEventListener(MouseEvent.CLICK, function(e: MouseEvent): void {
		//        var target: MovieClip = e.currentTarget as MovieClip;
		//        
		//        target.currentLoopFrame++;
