		    function initSystem() {
		        try {
		            var rawData = exportRoot.ScenarioData ? exportRoot.ScenarioData.rawData : null;
		            if (!rawData || rawData === "") return;
		
		            var lines = rawData.split(/\r?\n/);
		            allStepsData = [];
		            for (var i = 0; i < lines.length; i++) {
		                var line = lines[i];
		                if (line.length < 5) continue;
		                var p = line.split("|");
		                if (p.length >= 4 && p[1].trim() !== "") {
		                    allStepsData.push({
		                        scenario: p[0].trim(),
		                        id: p[1].trim(),
		                        vi: p[2] ? p[2].trim() : "",
		                        ru: p[3] ? p[3].trim() : "",
		                        target1: (p.length > 4) ? p[4].trim() : "",
		                        target2: (p.length > 5) ? p[5].trim() : "",
		                        speed: (p.length > 6) ? p[6].trim().toLowerCase() : "",
		                        timeScale: (p.length > 7) ? p[7].trim() : "1"
		                    });
		                }
		            }
		
		            errorList = [];
		            var rawErrors = exportRoot.ScenarioData ? exportRoot.ScenarioData.rawErrors : null;
		            if (rawErrors && rawErrors !== "") {
		                var errLines = rawErrors.split(/\r?\n/);
		                for (var j = 0; j < errLines.length; j++) {
		                    var ep = errLines[j].split("|");
		                    if (ep.length >= 2) errorList.push({ vi: ep[0].trim(), ru: ep[1].trim() });
		                }
		            }
		        } catch (e) { console.error("Lỗi data:", e); }
		    }
		
		    function sendLogToServer(action, detail, result) {
		        if (!exportRoot.currentUserID || exportRoot.currentUserID == -1) return;
		        var url = exportRoot.serverURL ? exportRoot.serverURL : "http://localhost:5000";
		        var params = new URLSearchParams();
		        params.append('uid', exportRoot.currentUserID);
		        params.append('act', action);
		        params.append('det', detail);
		        params.append('res', result);
		
		        fetch(url + "/api/log", {
		            method: 'POST',
		            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
		            body: params.toString()
		        }).catch(function (err) {});
		    }
		
		    function resolvePath(path) {
		        var parts = path.split(".");
		        var cur = _this;
		        function findChild(parent, baseName) {
		            if (!parent || !parent.children) return null;
		            for (var i = parent.children.length - 1; i >= 0; i--) {
		                var child = parent.children[i];
		                if (!child) continue;
		                if (child.name === baseName) return child;
		                if (child.children && child.children.length > 0) {
		                    var found = findChild(child, baseName);
		                    if (found) return found;
		                }
		            }
		            return null;
		        }
		
		        for (var i = 0; i < parts.length; i++) {
		            if (!cur) return null;
		            var nxt = cur[parts[i]] || cur.getChildByName(parts[i]);
		            if (!nxt && typeof cur.getNumChildren === "function") nxt = findChild(cur, parts[i]);
		            cur = nxt;
		            if (!cur) return null;
		        }
		        return cur;
		    }
		
		    function safeAddClick(btnName, cb) {
		        var btn = resolvePath(btnName);
		        if (btn) { btn.cursor = "pointer"; btn.removeAllEventListeners("click"); btn.on("click", cb); }
		    }
		
