		    function playAudioOffline(stepData, lang) {
		        stopCurrentSound();
		        if (isMuted) {
		            if (isAutoPlay) {
		                clearTimeout(autoNextTimeoutId);
		                autoNextTimeoutId = setTimeout(autoNextStep, 3000);
		            }
		            return;
		        }
		
		        var cleanSheetName = stepData.scenario.replace(/ /g, "_");
		        var langFolder = (lang === "vi") ? "VI" : "RU";
		        var btnID = stepData.id.replace(/\./g, "_");
		        var fileName = cleanSheetName + "_" + btnID + "_" + lang + "_" + userGender + ".mp3";
		        
		        tutorialAudio = new Audio(encodeURI(soundFolder + "/" + cleanSheetName + "/" + langFolder + "/" + fileName));
		        isAudioPlaying = true; 
		
		        tutorialAudio.onended = function () {
		            isAudioPlaying = false; 
		            if (isAutoPlay) {
		                clearTimeout(autoNextTimeoutId);
		                autoNextTimeoutId = setTimeout(autoNextStep, 1000);
		            }
		        };
		
		        var playPromise = tutorialAudio.play();
		        if (playPromise !== undefined) {
		            playPromise.catch(function (error) {
		                isAudioPlaying = false;
		                if (isAutoPlay) {
		                    clearTimeout(autoNextTimeoutId);
		                    autoNextTimeoutId = setTimeout(autoNextStep, 3000);
		                }
		            });
		        }
		    }
		
		    function playErrorSound(forcedID) {
		        if (isMuted) return;
		        var indexToPlay = (forcedID > 0) ? forcedID : (Math.floor(Math.random() * 4) + 1);
		        var fileUrl = encodeURI(soundFolder + "/System_Sounds/error_" + userLang + "_" + userGender + "_" + indexToPlay + ".mp3");
		        stopCurrentSound();
		        errorAudio = new Audio(fileUrl);
		        var p = errorAudio.play();
		        if (p !== undefined) p.catch(function (e) {});
		    }
		
		    function stopCurrentSound() {
		        isAudioPlaying = false;
		        clearTimeout(autoNextTimeoutId);
		        if (tutorialAudio) { tutorialAudio.pause(); tutorialAudio.currentTime = 0; tutorialAudio = null; }
		        if (errorAudio) { errorAudio.pause(); errorAudio.currentTime = 0; errorAudio = null; }
		    }
		
