		// ==============================================================
		// CÔNG CỤ DEBUG V4: TỰ ĐỘNG CHIA CỘT CHO EXCEL
		// ==============================================================
		
		var isDebugMode:Boolean = false; 
		
		// 1. Giao diện Tooltip
		var toolTipHolder:Sprite = new Sprite();
		var toolTipBg:Sprite = new Sprite();
		var txtPath:TextField = new TextField();
		
		var formatTip:TextFormat = new TextFormat("Arial", 13, 0xFFFF00, true);
		txtPath.defaultTextFormat = formatTip;
		txtPath.autoSize = TextFieldAutoSize.LEFT;
		txtPath.background = true;
		txtPath.backgroundColor = 0x000000;
		txtPath.border = true;
		txtPath.borderColor = 0xFFFFFF;
		txtPath.text = "Sẵn sàng...";
		
		toolTipHolder.addChild(toolTipBg);
		toolTipHolder.addChild(txtPath);
		toolTipHolder.mouseEnabled = false; 
		toolTipHolder.mouseChildren = false;
		toolTipHolder.visible = false; 
		stage.addChild(toolTipHolder); 
		
		var highlightBox:Sprite = new Sprite();
		highlightBox.mouseEnabled = false;
		stage.addChild(highlightBox);
		
		
		// ==============================================================
		// 2. NÚT BẬT/TẮT
		// ==============================================================
		var btnToggleDebug:Sprite = new Sprite();
		var txtToggle:TextField = new TextField();
		var formatBtn:TextFormat = new TextFormat("Arial", 12, 0xFFFFFF, true);
		
		txtToggle.defaultTextFormat = formatBtn;
		txtToggle.autoSize = TextFieldAutoSize.LEFT;
		txtToggle.selectable = false;
		txtToggle.mouseEnabled = false;
		
		btnToggleDebug.addChild(txtToggle);
		btnToggleDebug.buttonMode = true;
		btnToggleDebug.x = stage.stageWidth - 120; 
		btnToggleDebug.y = 10;
		stage.addChild(btnToggleDebug);
		
		function updateToggleButton():void {
		    btnToggleDebug.graphics.clear();
		    if (isDebugMode) {
		        btnToggleDebug.graphics.beginFill(0x009900); 
		        txtToggle.text = "🛠 DEBUG: ON ";
		    } else {
		        btnToggleDebug.graphics.beginFill(0x666666); 
		        txtToggle.text = "🛠 DEBUG: OFF";
		    }
		    btnToggleDebug.graphics.drawRoundRect(0, 0, txtToggle.width + 10, txtToggle.height + 4, 10);
		    btnToggleDebug.graphics.endFill();
		    txtToggle.x = 5; txtToggle.y = 2;
		}
		
		btnToggleDebug.addEventListener(MouseEvent.CLICK, function(e:MouseEvent):void {
		    isDebugMode = !isDebugMode; 
		    updateToggleButton();
		    applyDebugState();
		});
		
		function applyDebugState():void {
		    if (isDebugMode) {
		        // Bí quyết: Thêm true (Capture phase) và 99999 (Độ ưu tiên tuyệt đối)
		        // Bắt buộc Flash phải ưu tiên chạy tool Debug trước khi chạy các lệnh khóa của bài học
		        stage.addEventListener(MouseEvent.MOUSE_OVER, onDebugHover, true, 99999);
		        stage.addEventListener(MouseEvent.MOUSE_OUT, onDebugOut, true, 99999);
		        stage.addEventListener(MouseEvent.MOUSE_MOVE, onDebugMove, true, 99999);
		        stage.addEventListener(MouseEvent.CLICK, onDebugClick, true, 99999);
		    } else {
		        stage.removeEventListener(MouseEvent.MOUSE_OVER, onDebugHover, true);
		        stage.removeEventListener(MouseEvent.MOUSE_OUT, onDebugOut, true);
		        stage.removeEventListener(MouseEvent.MOUSE_MOVE, onDebugMove, true);
		        stage.removeEventListener(MouseEvent.CLICK, onDebugClick, true);
		        toolTipHolder.visible = false;
		        highlightBox.visible = false;
		        highlightBox.graphics.clear();
		    }
		}
		
		updateToggleButton();
