		    // =========================================================================================
		    function getRandomInt(min, max) { return min + Math.floor(Math.random() * (max - min + 1)); }
		
		    function timDoiTuong(mcCha, duongDan) {
		        var doiTuong = mcCha;
		        for (var i = 0; i < duongDan.length; i++) {
		            if (!doiTuong) return null;
		            var tenNut = duongDan[i];
		            var mChild = null;
		            var prop = doiTuong[tenNut];
		            
		            if (prop !== undefined && prop !== null) {
		                if (typeof prop.parent !== 'undefined' && prop.parent === null) mChild = null; 
		                else mChild = prop;
		            }
		
		            if (!mChild) {
		                for (var j = 0; j < 15; j++) {
		                    var suffixName = tenNut + "_" + j;
		                    var suffixProp = doiTuong[suffixName];
		                    if (suffixProp !== undefined && suffixProp !== null) {
		                        if (typeof suffixProp.parent === 'undefined' || suffixProp.parent !== null) { mChild = suffixProp; break; }
		                    }
		                }
		            }
		
		            if (!mChild && typeof doiTuong.getChildByName === 'function') mChild = doiTuong.getChildByName(tenNut);
		            if (!mChild && prop !== undefined) mChild = prop;
		
		            if (mChild) doiTuong = mChild; else return null;
		        }
		        return doiTuong;
		    }
		
		    function capNhatKim(mcCha, duongDan, gocXoay) { var doiTuong = timDoiTuong(mcCha, duongDan); if(doiTuong && typeof doiTuong.rotation !== 'undefined') doiTuong.rotation = gocXoay; }
		    function capNhatChu(mcCha, duongDan, noiDung) { var doiTuong = timDoiTuong(mcCha, duongDan); if (doiTuong && typeof doiTuong.text !== 'undefined') doiTuong.text = noiDung; }
		    function noiSuyKim(mcCha, duongDan, gocDich, tocDo) {
		        var doiTuong = timDoiTuong(mcCha, duongDan); if (!doiTuong || typeof doiTuong.rotation === 'undefined') return true; 
		        var diff = gocDich - doiTuong.rotation;
		        if (Math.abs(diff) < 0.5) { doiTuong.rotation = gocDich; return true; } else { doiTuong.rotation += diff * tocDo; return false; }
		    }
		    function noiSuyText(mcCha, duongDan, giaTriDich, tocDo) {
		        var doiTuong = timDoiTuong(mcCha, duongDan); if (!doiTuong || typeof doiTuong.text === 'undefined') return true;
		        var propName = "realVal_" + duongDan.join("_");
		        var hienTai; if (typeof mcCha[propName] !== 'undefined') { hienTai = mcCha[propName]; } else { hienTai = parseFloat(doiTuong.text); if (isNaN(hienTai)) hienTai = 0; }
		        var diff = giaTriDich - hienTai;
		        if (Math.abs(diff) < 0.1) { doiTuong.text = String(giaTriDich); delete mcCha[propName]; return true; } 
		        var buocNhay = diff * tocDo;
		        if (buocNhay > 0 && buocNhay < 0.05) buocNhay = 0.05; if (buocNhay < 0 && buocNhay > -0.05) buocNhay = -0.05;
		        var giaTriMoi = hienTai + buocNhay;
		        if (diff < 0 && giaTriMoi < giaTriDich) giaTriMoi = giaTriDich; if (diff > 0 && giaTriMoi > giaTriDich) giaTriMoi = giaTriDich;
		        mcCha[propName] = giaTriMoi; 
		        if (Math.abs(giaTriMoi) < 10 && Math.abs(giaTriMoi) > 0) doiTuong.text = giaTriMoi.toFixed(1); else doiTuong.text = giaTriMoi.toFixed(0);
		        return false; 
		    }
		
		    // =========================================================================================
		    // PHẦN 5: LOGIC ĐỘNG CƠ PHỤ (BCY)
