		    function updateGiamDanTungView(view, side) {
		        var isFinished = true, currentRPM = 0;
		        var dhName = "dongHoVongQuay" + side;
		        var rpmTextObj = timDoiTuong(view, [dhName, "vongQuay_txt"]);
		        if (!rpmTextObj || !rpmTextObj.parent) rpmTextObj = timDoiTuong(view, [dhName, "vongQuay_txt_2"]);
		        if (rpmTextObj && typeof rpmTextObj.text !== 'undefined') { currentRPM = parseFloat(rpmTextObj.text); if (isNaN(currentRPM)) currentRPM = 0; }
		
		        var tocDoGiam = (currentRPM < 5) ? 0.04 : (currentRPM < 15 ? 0.008 : 0.012); var tocDoNhiet = tocDoGiam * 0.3; 
		        var suffix = (side == "Trai") ? "lev" : "prav";
		
		        if (!noiSuyKim(view, [dhName, "kimCaoAp"], -80, tocDoGiam)) isFinished = false;
		        if (!noiSuyKim(view, [dhName, "kimCaoAp2"], -80, tocDoGiam)) isFinished = false;
		        if (!noiSuyKim(view, [dhName, "kimCaoAp3"], -80, tocDoGiam)) isFinished = false;
		
		        if (!noiSuyKim(view, [dhName, "kimThapAp"], -45, tocDoGiam)) isFinished = false;
		        if (!noiSuyKim(view, [dhName, "kimThapAp2"], -45, tocDoGiam)) isFinished = false;
		        if (!noiSuyKim(view, [dhName, "kimThapAp3"], -45, tocDoGiam)) isFinished = false;
		
		        if (!noiSuyKim(view, [dhName, "dongHoNhietDo", "kimNhietDo"], -135, tocDoNhiet)) isFinished = false;
		        if (!noiSuyKim(view, [dhName, "dongHoNhietDo", "kimNhietDo2"], -135, tocDoNhiet)) isFinished = false;
		
		        if (!noiSuyText(view, [dhName, "vongQuay_txt"], 0, tocDoGiam)) isFinished = false;
		        if (!noiSuyText(view, [dhName, "vongQuay_txt_2"], 0, tocDoGiam)) isFinished = false;
		
		        if (!noiSuyText(view, [dhName, "dongHoNhietDo", "nhietDo_txt"], 0, tocDoNhiet)) isFinished = false;
		        if (!noiSuyText(view, [dhName, "dongHoNhietDo", "nhietDo_txt_2"], 0, tocDoNhiet)) isFinished = false;
		
		        if (!noiSuyText(view, ["nhietDo_" + side + "_txt"], 0, tocDoNhiet)) isFinished = false;
		        if (!noiSuyText(view, ["nhietDo_" + side + "_txt_2"], 0, tocDoNhiet)) isFinished = false;
		        
		        if (!noiSuyText(view, ["nhiet_do_nd_" + suffix], 25, tocDoNhiet)) isFinished = false;
		        if (!noiSuyText(view, ["ap_suat_nd_" + suffix], 0, tocDoGiam)) isFinished = false;
		
		        return isFinished;
		    }
		
		    // =========================================================================================
