		    function xuLyClickChuyenCheDo(e) {
		        var isFrame2 = false;
		        // Check frame 1 theo JS = frame 2 AS3
		        if (_this.manHinhChinh.manHinhTrai && _this.manHinhChinh.manHinhTrai.currentFrame === 1) isFrame2 = true;
		        if (_this.manHinhChinh.manHinhGiua && _this.manHinhChinh.manHinhGiua.currentFrame === 1) isFrame2 = true;
		        if (_this.manHinhChinh.manHinhPhai && _this.manHinhChinh.manHinhPhai.currentFrame === 1) isFrame2 = true;
		        if (isFrame2 === false) return; 
		
		        var tenNut = e.target.name;
		        var tenNutCha = (e.target.parent && e.target.parent.name) ? e.target.parent.name : "";
		
		        if (tenNut == "cay_du_phong_trai" || tenNutCha == "cay_du_phong_trai") { luaChonTam_Trai = "DU_PHONG"; } 
		        else if (tenNut == "cay_chinh_trai" || tenNutCha == "cay_chinh_trai") { luaChonTam_Trai = "CHINH"; } 
		        else if (tenNut == "btn_bask" || tenNutCha == "btn_bask") { luaChonTam_Phai = "DU_PHONG"; } 
		        else if (tenNut == "cay_chinh_phai" || tenNutCha == "cay_chinh_phai") { luaChonTam_Phai = "CHINH"; } 
		        else if (tenNut == "truy_cap" || tenNutCha == "truy_cap") {
		            if (luaChonTam_Trai != "") { _this.cheDoDieuKhien_Trai = luaChonTam_Trai; luaChonTam_Trai = ""; console.log(">> Động cơ TRÁI chuyển sang: " + _this.cheDoDieuKhien_Trai); }
		            if (luaChonTam_Phai != "") { _this.cheDoDieuKhien_Phai = luaChonTam_Phai; luaChonTam_Phai = ""; console.log(">> Động cơ PHẢI chuyển sang: " + _this.cheDoDieuKhien_Phai); }
		        }
		    }
		
		    // =========================================================================================
