		    function truyQuetVaGhimKimThapAp(rootMC, gocXoayLoi, sidePrefix) {
		        if (!rootMC || !rootMC.children) return;
		        for (var i = 0; i < rootMC.children.length; i++) {
		            var child = rootMC.children[i];
		            if (child && (child.name == "kimThapAp" || child.name == "kimThapAp3")) {
		                var matchSide = false; var currentParent = child.parent;
		                for (var depth = 0; depth < 3; depth++) {
		                    if (currentParent && currentParent.name) {
		                        if (currentParent.name.toLowerCase().indexOf(sidePrefix) != -1) { matchSide = true; break; }
		                    }
		                    if (currentParent) currentParent = currentParent.parent; else break;
		                }
		                if (matchSide) child.rotation = gocXoayLoi;
		            }
		            if (child && child.children) truyQuetVaGhimKimThapAp(child, gocXoayLoi, sidePrefix);
		        }
		    }
		
		    function apDungHieuUngPan(view, side) {
		        if (!view) return;
		        var stop_MC = _this["stop_" + side];
		        if (stop_MC && stop_MC.currentFrame === 0) return;
		
		        var vCount = (side == "Trai") ? vCount_DC1_Trai : vCount_DC1_Phai;
		        var thoiGianMs = (vCount / 30) * 1000;
		        var rpmChuan = vCount / 30;
		        
		        var dhName = "dongHoVongQuay" + side;
		        var denKD = layLinhKienTuCache(view, [dhName, "denKD"]);
		        var isDongCoDangChay = (denKD != null && denKD.currentFrame == 1) || vCount > 0;
		
		        for (var i=0; i<danhSachPan.length; i++) {
		            var pan = danhSachPan[i];
		            if (pan.dongCo == side.toUpperCase() && pan.trangThai == STATE_CHO_TRIGGER) {
		                if (!isDongCoDangChay) continue;
		                if (pan.id.indexOf("PAN_03")!==-1 || pan.id.indexOf("PAN_04")!==-1 || pan.id.indexOf("PAN_06")!==-1 || pan.id.indexOf("PAN_07")!==-1) {
		                    pan.trangThai = STATE_XAY_RA;
		                } else if ((pan.kieuTrigger == "RPM_CA" && rpmChuan >= pan.giaTriTrigger) || (pan.kieuTrigger == "TIME" && thoiGianMs >= pan.giaTriTrigger)) {
		                    pan.trangThai = STATE_XAY_RA;
		                }
		            }
		        }
		
		        var suffix = (side == "Trai") ? "lev" : "prav";
		        var prefixSearch = (side == "Trai") ? "trai" : "phai";
		
		        for (var i=0; i<danhSachPan.length; i++) {
		            var panActive = danhSachPan[i];
		            if (panActive.dongCo == side.toUpperCase() && panActive.trangThai == STATE_XAY_RA) {
		                if (panActive.id.indexOf("PAN_01_KET_CAO_AP") !== -1) {
		                    capNhatKimNhanh(view, [dhName, "kimThapAp"], -45); capNhatKimNhanh(view, [dhName, "kimThapAp3"], -45);
		                    var rpmBiGhim = 2.5 + Math.sin(thoiGianMs / 150) * 0.3;
		                    var gocCaoAp_Loi = (rpmBiGhim * 3 - 80);
		                    capNhatKimNhanh(view, [dhName, "kimCaoAp"], gocCaoAp_Loi); capNhatKimNhanh(view, [dhName, "kimCaoAp3"], gocCaoAp_Loi);
		                    capNhatChuNhanh(view, [dhName, "vongQuay_txt"], rpmBiGhim.toFixed(1));
		                    
		                    var nhietDoT4 = (thoiGianMs < 15000) ? (25 + ((thoiGianMs - 5000) / 25)) : (225 + ((thoiGianMs - 10000) / 20));
		                    if (nhietDoT4 >= 750) { 
		                        if (stop_MC && stop_MC.currentFrame !== 0) stop_MC.gotoAndStop(0); 
		                        if (side=="Trai") xuLyKhiTatMay_Trai(view); else xuLyKhiTatMay_Phai(view); 
		                        return; 
		                    }
		                    capNhatKimNhanh(view, [dhName, "dongHoNhietDo", "kimNhietDo"], nhietDoT4 * 0.3 - 135);
		                    capNhatChuNhanh(view, [dhName, "dongHoNhietDo", "nhietDo_txt"], nhietDoT4.toFixed(0));
		                    capNhatChuNhanh(view, ["nhietDo_" + side + "_txt"], nhietDoT4.toFixed(0));
		                }
		                else if (panActive.id.indexOf("PAN_02_KET_THAP_AP") !== -1) {
		                    var rpmThapAp_Loi = 1.5 + (Math.sin(thoiGianMs / 80) * 0.5);
		                    truyQuetVaGhimKimThapAp(view, -45 + (rpmThapAp_Loi * 2.55), prefixSearch);
		                    var txtNhietGoc = layLinhKienTuCache(view, [dhName, "dongHoNhietDo", "nhietDo_txt"]);
		                    if (txtNhietGoc && typeof txtNhietGoc.text !== 'undefined') {
		                        var nhietDoGoc = parseFloat(txtNhietGoc.text) || 25;
		                        var nhietDoT4_Loi = (thoiGianMs > 10000) ? (nhietDoGoc + ((thoiGianMs - 10000) / 80)) : nhietDoGoc;
		                        if (nhietDoT4_Loi >= 730) nhietDoT4_Loi = 730 + (Math.random() * 4 - 2);
		                        capNhatKimNhanh(view, [dhName, "dongHoNhietDo", "kimNhietDo"], nhietDoT4_Loi * 0.3 - 135);
		                        capNhatChuNhanh(view, [dhName, "dongHoNhietDo", "nhietDo_txt"], nhietDoT4_Loi.toFixed(0));
		                    }
		                }
		                else if (panActive.id.indexOf("PAN_03_KO_TANG_NHIET") !== -1) {
		                    var vCount2 = (side=="Trai") ? vCount_DC2_Trai : vCount_DC2_Phai;
		                    var giayThuc = vCount2 / 100;
		                    var rpmCA_Loi = giayThuc > 30 ? 30 : giayThuc;
		                    var hienThiCA = (rpmCA_Loi == 30) ? (30 + (Math.random() * 0.15)) : rpmCA_Loi;
		                    capNhatKimNhanh(view, [dhName, "kimCaoAp"], (hienThiCA * 3 - 80));
		                    capNhatChuNhanh(view, [dhName, "vongQuay_txt"], hienThiCA.toFixed(1));
		                    if (rpmCA_Loi >= 18) {
		                        var rpmTA_Loi = ((rpmCA_Loi - 18) / 12) * 7;
		                        if (rpmTA_Loi > 7) rpmTA_Loi = 7;
		                        truyQuetVaGhimKimThapAp(view, -45 + ((rpmTA_Loi == 7 ? 7 + Math.random()*0.1 : rpmTA_Loi) * 2.55), prefixSearch);
		                    } else { truyQuetVaGhimKimThapAp(view, -45, prefixSearch); }
		                    if (giayThuc > 38) {
		                        if (stop_MC && stop_MC.currentFrame !== 0) stop_MC.gotoAndStop(0); 
		                        if(side=="Trai") xuLyKhiTatMay_Trai(view); else xuLyKhiTatMay_Phai(view);
		                    }
		                }
		            }
		        }
		    }
		
		    // =========================================================================================
		    // [THÊM TÍNH NĂNG]: PHẦN 10 - BỘ QUÁN TÍNH ĐỘNG CƠ & SƯỞI ẤM (Physics Engine)
		    // =========================================================================================
		    function khoiTaoTayDau() {
		        if (!_this.daKhoiTaoTayDau && _this.rud_LeftRight) {
		            _this.daKhoiTaoTayDau = true;
		            var rLR = _this.rud_LeftRight;
		            if (rLR.rud_left && rLR.thangdo) {
		                var minY = -rLR.thangdo.nominalBounds.height;
		                rLR.rud_left.on("pressmove", function (e) {
		                    var p = rLR.globalToLocal(e.stageX, e.stageY);
		                    e.currentTarget.y = Math.min(0, Math.max(minY, p.y));
		                });
		                rLR.rud_right.on("pressmove", function (e) {
		                    var p = rLR.globalToLocal(e.stageX, e.stageY);
		                    e.currentTarget.y = Math.min(0, Math.max(minY, p.y));
		                });
		            }
		        }
		    }
		
		    function loopToanHeThong() {
		        var rLR = _this.rud_LeftRight;
		        var rawLeverTrai = (rLR && rLR.rud_left) ? (-rLR.rud_left.y * 0.53 / 9) : 0;
		        var rawLeverPhai = (rLR && rLR.rud_right) ? (-rLR.rud_right.y * 0.53 / 9) : 0;
		
		        tinhQuanTinhDongCo("Trai", rawLeverTrai, vCount_DC1_Trai, _this.stop_Trai);
		        tinhQuanTinhDongCo("Phai", rawLeverPhai, vCount_DC1_Phai, _this.stop_Phai);
		
		        if (_this.manHinhChinh) {
		            var screens = [_this.manHinhChinh.manHinhTrai, _this.manHinhChinh.manHinhGiua, _this.manHinhChinh.manHinhPhai];
		            for (var i = 0; i < screens.length; i++) {
		                if (screens[i]) capNhatGiaoDienDongBo(screens[i], rawLeverTrai, rawLeverPhai);
		            }
		        }
		    }
		
		    function tinhQuanTinhDongCo(side, rawLeverVal, vCount, stopMC) {
		        var isStarting = (stopMC != null && stopMC.currentFrame !== 0 && vCount < 1845);
		        var isRunning = (stopMC != null && stopMC.currentFrame !== 0 && vCount >= 1845);
		        var nvd_target = 0, nnd_target = 0, temp_target = 25, oil_p_target = 0, oil_t_target = 25;
		
		        var cheDo = (side == "Trai") ? _this.cheDoDieuKhien_Trai : _this.cheDoDieuKhien_Phai;
		        if (cheDo == "DU_PHONG" && rawLeverVal > 6.5) rawLeverVal = ((12 + rawLeverVal) >= 48.9) ? 39.9 : 20.0;
		
		        if (isStarting) {
		            nvd_target = vCount / 30;
		            nnd_target = (nvd_target < 18.43) ? 0 : ((nvd_target - 18.43) / 43.17) * 30.0;
		            temp_target = Math.max(25, (vCount / 2.3) - 200);
		            oil_p_target = vCount / 550;
		            oil_t_target = 25 + (vCount / 27);
		        } else if (isRunning) {
		            if (rawLeverVal <= 6.5) {
		                nvd_target = 61.6; nnd_target = 30.0;
		                temp_target = (side == "Trai") ? idle_nhietDoText_Trai : idle_nhietDoText_Phai;
		                oil_p_target = (side == "Trai") ? idle_apSuat_Trai : idle_apSuat_Phai;
		                oil_t_target = (side == "Trai") ? idle_nhietDoND_Trai : idle_nhietDoND_Phai;
		            } else {
		                var mapV = function (v, iM, ix, oM, ox) { if (v <= iM) return oM; if (v >= ix) return ox; return oM + (v - iM) * (ox - oM) / (ix - iM); };
		                nvd_target = mapV(rawLeverVal, 6.5, 45, 61.6, 100.0);
		                nnd_target = mapV(rawLeverVal, 6.5, 45, 30.0, 100.0);
		                temp_target = mapV(rawLeverVal, 6.5, 45, 441, 650);
		                oil_p_target = mapV(rawLeverVal, 6.5, 45, 3.4, 4.8);
		                oil_t_target = mapV(rawLeverVal, 6.5, 45, 68.5, 95);
		            }
		        }
		
		        var apply = function (curr, target, spd) { var diff = target - curr; if (Math.abs(diff) < 0.1) return target; return curr + diff * spd; };
		
		        if (side == "Trai") {
		            _this.real_nvd_trai = apply(_this.real_nvd_trai, nvd_target, 0.05); _this.real_nnd_trai = apply(_this.real_nnd_trai, nnd_target, 0.03);
		            _this.real_temp_trai = apply(_this.real_temp_trai, temp_target, 0.02); _this.real_oil_p_trai = apply(_this.real_oil_p_trai, oil_p_target, 0.08);
		            _this.real_oil_t_trai = apply(_this.real_oil_t_trai, oil_t_target, 0.01);
		        } else {
		            _this.real_nvd_phai = apply(_this.real_nvd_phai, nvd_target, 0.05); _this.real_nnd_phai = apply(_this.real_nnd_phai, nnd_target, 0.03);
		            _this.real_temp_phai = apply(_this.real_temp_phai, temp_target, 0.02); _this.real_oil_p_phai = apply(_this.real_oil_p_phai, oil_p_target, 0.08);
		            _this.real_oil_t_phai = apply(_this.real_oil_t_phai, oil_t_target, 0.01);
		        }
		    }
		
		    function capNhatGiaoDienDongBo(mc, rawTrai, rawPhai) {
		        var heSo = Math.sqrt(288 / (_this.nhietDoMoiTruong + 273));
		        var isL = (mc.currentFrame == 17 || mc.name == "manHinhTrai" || mc.name == "manHinhGiua"); // Frame 18 AS3 = 17 JS
		
		        if (mc.nhiet_do_nd_lev) mc.nhiet_do_nd_lev.text = _this.real_oil_t_trai.toFixed(1);
		        if (mc.ap_suat_nd_lev) mc.ap_suat_nd_lev.text = _this.real_oil_p_trai.toFixed(1);
		        if (mc.nhiet_do_nd_prav) mc.nhiet_do_nd_prav.text = _this.real_oil_t_phai.toFixed(1);
		        if (mc.ap_suat_nd_prav) mc.ap_suat_nd_prav.text = _this.real_oil_p_phai.toFixed(1);
		
		        if (mc.currentFrame == 17 || mc.currentFrame == 18) { 
		            var raw = isL ? rawTrai : rawPhai, nvd = isL ? _this.real_nvd_trai : _this.real_nvd_phai, nnd = isL ? _this.real_nnd_trai : _this.real_nnd_phai;
		            var tmp = isL ? _this.real_temp_trai : _this.real_temp_phai, op = isL ? _this.real_oil_p_trai : _this.real_oil_p_phai, ot = isL ? _this.real_oil_t_trai : _this.real_oil_t_phai;
		
		            var rud_disp = (raw < 5.5) ? 12.0 : ((raw < 6.5) ? 17.7 : (12 + raw));
		            if (mc.txt_rud) mc.txt_rud.text = rud_disp.toFixed(1); if (mc.txt_nvd) mc.txt_nvd.text = nvd.toFixed(1);
		            if (mc.txt_nnd) mc.txt_nnd.text = nnd.toFixed(1); if (mc.txt_nvd_pr) mc.txt_nvd_pr.text = (nvd * heSo).toFixed(1);
		            if (mc.txt_nnd_pr) mc.txt_nnd_pr.text = (nnd * heSo).toFixed(1); if (mc.txt_temp) mc.txt_temp.text = tmp.toFixed(0);
		            if (mc.txt_oil_press) mc.txt_oil_press.text = op.toFixed(1); if (mc.txt_oil_temp) mc.txt_oil_temp.text = ot.toFixed(0);
		            if (mc.txt_thong_bao_phai) mc.txt_thong_bao_phai.text = isL ? "САУ СУ л исправна" : "САУ СУ п исправна";
		        }
		
		        function updateGauges(dialName, nvd, tmp, isLeft) {
		            if (!mc[dialName]) return; var dial = mc[dialName];
		            if (dial.daiSuoiAmDC) {
		                if (_this.SUOI_AM_STATE == null) _this.SUOI_AM_STATE = { T_D: false, T_R: false, T_S: 0, P_D: false, P_R: false, P_S: 0 };
		                var S = _this.SUOI_AM_STATE, pre = isLeft ? "T_" : "P_";
		                if (nvd < 5) {
		                    S[pre+"D"] = false; S[pre+"R"] = false; dial.daiSuoiAmDC.gotoAndStop(0);
		                } else if (nvd > 61.5) {
		                    if (S[pre+"D"] == true) dial.daiSuoiAmDC.gotoAndStop(0); 
		                    else {
		                        dial.daiSuoiAmDC.gotoAndStop(1); // Bật dải sưởi
		                        if (nvd >= 72.0 && nvd <= 78.0) {
		                            if (S[pre+"R"] == false) { S[pre+"R"] = true; S[pre+"S"] = getTimer(); } 
		                            else { if (getTimer() - S[pre+"S"] >= 90000) { S[pre+"D"] = true; S[pre+"R"] = false; dial.daiSuoiAmDC.gotoAndStop(0); } }
		                        } else S[pre+"R"] = false; 
		                    }
		                }
		            }
		        }
		        updateGauges("dongHoVongQuayTrai", _this.real_nvd_trai, _this.real_temp_trai, true);
		        updateGauges("dongHoVongQuayPhai", _this.real_nvd_phai, _this.real_temp_phai, false);
		    }
