		    // =============================================================
		    // 0. CHUẨN BỊ LOGIC CHẠY CÁNH LÁI (THUẬT TOÁN SÓNG SIN)
		    // =============================================================
		    if (exportRoot.globalTestTime == null) exportRoot.globalTestTime = 0.0;
		    exportRoot.isTesting_CanhLai = false;
		
		    function onLoopTestCanhLai(e) {
		        if (!exportRoot.isTesting_CanhLai) return;
		        exportRoot.globalTestTime += 0.02;
		        var t = exportRoot.globalTestTime;
		        
		        var rawWave = Math.sin(t) + 0.3 * Math.sin(t * 2.3);
		        var testProgress = (rawWave + 1.3) / 2.6;
		        if (testProgress < 0) testProgress = 0;
		        if (testProgress > 1) testProgress = 1;
		
		        var mhChinh = exportRoot.manHinhChinh || _this.manHinhChinh;
		        if (!mhChinh) return;
		
		        var screens = [mhChinh.manHinhTrai, mhChinh.manHinhPhai, mhChinh.manHinhGiua];
		        for (var i = 0; i < screens.length; i++) {
		            var s = screens[i];
		            if (s && s.currentFrame === 8) { 
		                if (s.rul_huong && s.thang_do_rul_huong) {
		                    var sh = s.thang_do_rul_huong;
		                    var wH = sh.nominalBounds ? sh.nominalBounds.width : 100;
		                    s.rul_huong.x = (sh.x - (wH / 2)) + testProgress * wH;
		                }
		                if (s.thang_do_rul_lieng) {
		                    var sl = s.thang_do_rul_lieng;
		                    var hL = sl.nominalBounds ? sl.nominalBounds.height : 100;
		                    var vY = (sl.y - (hL / 2)) + testProgress * hL;
		                    if (s.rul_lieng_1) s.rul_lieng_1.y = vY;
		                    if (s.rul_lieng_2) s.rul_lieng_2.y = vY;
		                }
		                if (s.rul_len_xuong && s.thang_do_rul_len_xuong) {
		                    var slx = s.thang_do_rul_len_xuong;
		                    var hLx = slx.nominalBounds ? slx.nominalBounds.height : 100;
		                    s.rul_len_xuong.y = (slx.y + (hLx / 2)) - testProgress * hLx;
		                }
		            }
		        }
		    }
		    createjs.Ticker.addEventListener("tick", onLoopTestCanhLai);
		
		    // =============================================================
