		    // =============================================================
		    // 2. HÀM XỬ LÝ CHUNG & KHIÊN BẢO VỆ TỐI THƯỢNG
		    // =============================================================
		    function toggleSwitch(btn, key) {
		        var now = Date.now();
		        if (btn && btn._lastToggle && (now - btn._lastToggle < 250)) return tt[key];
		        if (btn) btn._lastToggle = now;
		
		        if (exportRoot._lastSoundTime === undefined) exportRoot._lastSoundTime = 0;
		        if (now - exportRoot._lastSoundTime > 150) {
		            try { 
		                createjs.Sound.stop("Sound_CongTacClass");
		                createjs.Sound.play("Sound_CongTacClass", {interrupt: createjs.Sound.INTERRUPT_ANY}); 
		                exportRoot._lastSoundTime = now;
		            } catch(e) {} 
		        }
		        
		        tt[key] = !tt[key]; 
		        if (btn && typeof btn.gotoAndStop === "function") btn.gotoAndStop(tt[key] ? 0 : 1);
		        return tt[key]; 
		    }
		
		    // 🚀 LỚP KHIÊN HỦY DIỆT MỌI ĐOẠN CODE RÁC KHÁC
		    function bindRobustClick(btn, handler) {
		        if (!btn) return;
		        btn.cursor = "pointer";
		        btn.mouseChildren = false; 
		        
		        btn.removeAllEventListeners("mousedown");
		        btn.removeAllEventListeners("click");
		        
		        btn.on("mousedown", function(e) {
		            // Lệnh sát thủ: Cắt đứt toàn bộ các sự kiện mousedown/click khác đang bám trên nút này hoặc parent của nó
		            if (e.stopImmediatePropagation) e.stopImmediatePropagation();
		            if (e.nativeEvent) {
		                if (e.nativeEvent.stopImmediatePropagation) e.nativeEvent.stopImmediatePropagation();
		                if (e.nativeEvent.preventDefault) e.nativeEvent.preventDefault();
		            }
		
		            var now = Date.now();
		            if (btn._lastClick && (now - btn._lastClick < 300)) return;
		            btn._lastClick = now;
		
		            handler(e);
		        });
		
		        btn.on("click", function(e) {
		            if (e.stopImmediatePropagation) e.stopImmediatePropagation();
		            if (e.nativeEvent) {
		                if (e.nativeEvent.stopImmediatePropagation) e.nativeEvent.stopImmediatePropagation();
		                if (e.nativeEvent.preventDefault) e.nativeEvent.preventDefault();
		            }
		        });
		    }
		
		    function safeResetTimers() {
		        try {
		            var timers = [
		                exportRoot.myTimer_DC1_Trai, exportRoot.myTimer_DC2_Trai, exportRoot.myTimer_DC3_Trai, exportRoot.myTimer_DC4_Trai, exportRoot.myTimer_DC5_Trai,
		                exportRoot.myTimer_DC1_Phai, exportRoot.myTimer_DC2_Phai, exportRoot.myTimer_DC3_Phai, exportRoot.myTimer_DC4_Phai, exportRoot.myTimer_DC5_Phai
		            ];
		            for (var i = 0; i < timers.length; i++) { if (timers[i] && typeof timers[i].reset === "function") timers[i].reset(); }
		        } catch(e) {}
		    }
		
		    function setChildFrame(parentMC, childName, frameJS) {
		        var child = parentMC.getChildByName(childName) || parentMC[childName]; 
		        if (child && typeof child.gotoAndStop === "function") {
		            if (child.currentFrame !== frameJS) child.gotoAndStop(frameJS);
		        }
		    }
		
		    function updateScreenVisibility() {
		        var isPowered = (akum_lev_code === 0 || akum_prav_code === 0 || gen_lev_active === 0 || gen_prav_active === 0);
		        var mainScr = exportRoot.manHinhChinh || _this.manHinhChinh;
		        if (!mainScr) return;
		
		        if (isPowered) {
		            if (mainScr.manHinhTrai && mainScr.manHinhTrai.currentFrame === 0) { mainScr.manHinhTrai.gotoAndStop(20); bindScreenButtons(mainScr.manHinhTrai); }
		            if (mainScr.manHinhGiua && mainScr.manHinhGiua.currentFrame === 0) { mainScr.manHinhGiua.gotoAndStop(7);  bindScreenButtons(mainScr.manHinhGiua); }
		            if (mainScr.manHinhPhai && mainScr.manHinhPhai.currentFrame === 0) { mainScr.manHinhPhai.gotoAndStop(3);  bindScreenButtons(mainScr.manHinhPhai); }
		        } else {
		            if (mainScr.manHinhTrai) { mainScr.manHinhTrai.gotoAndStop(0); mainScr.manHinhTrai.isBound = false; }
		            if (mainScr.manHinhGiua) { mainScr.manHinhGiua.gotoAndStop(0); mainScr.manHinhGiua.isBound = false; }
		            if (mainScr.manHinhPhai) { mainScr.manHinhPhai.gotoAndStop(0); mainScr.manHinhPhai.isBound = false; }
		        }
		    }
		
		    // =============================================================
		    // 3. ĐỒNG BỘ TRẠNG THÁI (Chỉ cập nhật đèn báo)
		    // =============================================================
		    function syncVisualsLoop(e) {
		        var mainScr = exportRoot.manHinhChinh || _this.manHinhChinh;
		        if (!mainScr) return;
		        
		        var isVcyRunning = (exportRoot.APP_STATE === "FINISHED");
		        var isLeftRunning = (exportRoot.real_nvd_trai > 40 || exportRoot.vCount_DC1_Trai > 1500);
		        var isRightRunning = (exportRoot.real_nvd_phai > 40 || exportRoot.vCount_DC1_Phai > 1500);
		
		        var real_gen_lev_active = (!tt.gen_lev && isLeftRunning) ? 0 : 1;
		        var real_gen_prav_active = (!tt.gen_prav && isRightRunning) ? 0 : 1;
		        
		        if (gen_lev_active !== real_gen_lev_active || gen_prav_active !== real_gen_prav_active) {
		            gen_lev_active = real_gen_lev_active;
		            gen_prav_active = real_gen_prav_active;
		            updateScreenVisibility(); 
		        }
		
		        var screens = [mainScr.manHinhTrai, mainScr.manHinhGiua, mainScr.manHinhPhai];
		        for (var i = 0; i < screens.length; i++) {
		            var s = screens[i];
		            if (!s) continue;
		            if (s.currentFrame === 7) { 
		                setChildFrame(s, "mayPhat_DC_Trai", (!tt.gen_lev && isLeftRunning) ? 1 : 0);
		                setChildFrame(s, "mayPhat_DC_Phai", (!tt.gen_prav && isRightRunning) ? 1 : 0);
		                setChildFrame(s, "mayPhat_VCY",   (!tt.gen_vcy && isVcyRunning) ? 1 : 0);
		            }
		            if (s.currentFrame === 4) { 
		                setChildFrame(s, "bomNLDay", tt.topl ? 0 : 1);
		                setChildFrame(s, "bomNLKD",  tt.topl ? 0 : 1);
		            }
		        }
		    }
		    createjs.Ticker.addEventListener("tick", syncVisualsLoop); 
		
		    // =============================================================
		    // 4. MÁY TRẠNG THÁI MÀN HÌNH CHUẨN ĐOÁN
		    // =============================================================
		    function bindScreenButtons(mc) {
		        if (!mc || mc.isBound) return; 
		        mc.isBound = true; 
		        if (isNaN(mc.fotoAktif)) mc.fotoAktif = 1; 
		        if (isNaN(mc.stepFrame)) mc.stepFrame = 21; 
		
		        if (!mc.eventTracker) mc.eventTracker = {};
		
		        function getMC(name) { return mc[name] || mc.getChildByName(name); }
		
		        function bindClick(btnName, newFunc) {
		            var btn = getMC(btnName);
		            if (!btn) return;
		            if (mc.eventTracker[btnName]) btn.off("mousedown", mc.eventTracker[btnName]);
		            
		            btn.cursor = "pointer"; btn.mouseChildren = false; 
		            mc.eventTracker[btnName] = btn.on("mousedown", function(e) {
		                if (e.stopImmediatePropagation) e.stopImmediatePropagation();
		                if (e.nativeEvent) { 
		                    if(e.nativeEvent.stopImmediatePropagation) e.nativeEvent.stopImmediatePropagation();
		                    if(e.nativeEvent.preventDefault) e.nativeEvent.preventDefault();
		                }
		                var now = Date.now();
		                if (btn._lastC && (now - btn._lastC < 250)) return;
		                btn._lastC = now;
		                newFunc(e);
		            });
		        }
		
		        function unbindAllDynamic() {
		            var dBtns = ["btn_dvig", "btn_topl", "btn_gidr", "btn_czo", "btn_cec", "btn_kcy", "btn_avtk", "btn_vuxd", "btn_lev"];
		            for (var i = 0; i < dBtns.length; i++) {
		                var b = getMC(dBtns[i]);
		                if (b && mc.eventTracker[dBtns[i]]) { b.off("mousedown", mc.eventTracker[dBtns[i]]); delete mc.eventTracker[dBtns[i]]; }
		            }
		        }
		
		        bindClick("btn_kiss", function(){ mc.gotoAndStop(3); unbindAllDynamic(); refreshMenuButtons(); });
		        bindClick("btn_pil",  function(){ unbindAllDynamic(); mc.gotoAndStop(34); }); 
		        bindClick("btn_nvg",  function(){ unbindAllDynamic(); mc.gotoAndStop(35); }); 
		        bindClick("btn_ito",  function(){ unbindAllDynamic(); mc.gotoAndStop(36); }); 
		        
		        bindClick("btn_bask", function(e) { 
		            var p = e.target; var pScr = null; var mhChinh = exportRoot.manHinhChinh || _this.manHinhChinh;
		            while (p && p !== _this.stage) {
		                if (mhChinh && (p === mhChinh.manHinhTrai || p === mhChinh.manHinhGiua || p === mhChinh.manHinhPhai)) { pScr = p; break; }
		                p = p.parent;
		            }
		            if (pScr && pScr.currentFrame === 1) return; 
		            enterTruocBay(); 
		        });
		
		        function refreshMenuButtons() {
		            setTimeout(function() {
		                bindClick("btn_dvig", function(){ mc.gotoAndStop(1); refreshMenuButtons(); });
		                bindClick("btn_topl", function(){ mc.gotoAndStop(4); refreshMenuButtons(); });
		                bindClick("btn_gidr", function(){ mc.gotoAndStop(5); refreshMenuButtons(); });
		                bindClick("btn_czo",  function(){ mc.gotoAndStop(6); refreshMenuButtons(); });
		                bindClick("btn_cec",  function(){ mc.gotoAndStop(7); refreshMenuButtons(); });
		                bindClick("btn_kcy",  function(){ mc.gotoAndStop(8); refreshMenuButtons(); });
		            }, 20); 
		        }
		
		        function enterTruocBay() {
		            mc.stepFrame = 21; mc.gotoAndStop(20); 
		            var scr = getMC("scroll_avtk"); if(scr) scr.gotoAndStop(0);
		            unbindAllDynamic();
		            bindClick("btn_dvig", function() {
		                var s = mc.stepFrame;
		                if (s >= 21 && s <= 31) { 
		                    var nF = s + 1; mc.gotoAndStop(nF - 1);
		                    var mh = exportRoot.manHinhChinh || _this.manHinhChinh;
		                    if (nF === 23) { if(mh && mh.manHinhGiua) mh.manHinhGiua.gotoAndStop(1); } 
		                    else if (nF === 28) { if(mh && mh.manHinhGiua) mh.manHinhGiua.gotoAndStop(32); } 
		                    else if (nF === 29) { if(mh && mh.manHinhGiua) mh.manHinhGiua.gotoAndStop(1); }
		                    mc.stepFrame = nF;
		                }
		            });
		            bindClick("btn_avtk", function(){
		                mc.gotoAndStop(15); unbindAllDynamic();
		                setTimeout(function() {
		                    var sa = getMC("scroll_avtk"); if(sa) { sa.visible = true; sa.gotoAndStop(0); }
		                    bindClick("btn_kcy", function(){ var s = getMC("scroll_avtk"); if(s) { var f=s.currentFrame+1; if(f>=s.totalFrames) f=0; s.gotoAndStop(f); } });
		                    bindClick("btn_cec", function(){ var s = getMC("scroll_avtk"); if(s) { var f=s.currentFrame-1; if(f<0) f=s.totalFrames-1; s.gotoAndStop(f); } });
		                    bindClick("btn_czo", function(){
		                        var sa = getMC("scroll_avtk"); if(!sa) return; var f=sa.currentFrame; sa.visible = false;
		                        if (f===14) mc.gotoAndStop(16); else if (f===15) mc.gotoAndStop(17); else if (f===16) mc.gotoAndStop(18); else { sa.visible = true; return; }
		                        unbindAllDynamic(); bindClick("btn_vuxd", function(){ enterTruocBay(); });
		                        if(mc.currentFrame===17) bindClick("btn_gidr", function(){ mc.gotoAndStop(18); unbindAllDynamic(); bindClick("btn_vuxd", function(){ enterTruocBay(); }); bindClick("btn_lev", function(){ mc.gotoAndStop(17); }); });
		                        else if(mc.currentFrame===18) bindClick("btn_lev", function(){ mc.gotoAndStop(17); unbindAllDynamic(); bindClick("btn_vuxd", function(){ enterTruocBay(); }); bindClick("btn_gidr", function(){ mc.gotoAndStop(18); }); });
		                    });
		                }, 20);
		            });
		        }
		
		        if (mc.currentFrame === 20) enterTruocBay();
		        if (mc.currentFrame === 3) { mc.gotoAndStop(3); refreshMenuButtons(); }
		    }
		
		    // =============================================================
